    protected PreferenceDataStore createPreferenceDataStore(@NonNull Context context) {
        TermuxAppSharedPreferences preferences = TermuxAppSharedPreferences.build(context, true);
        if (preferences == null) return null;

        return new MappedPreferenceDataStore.Builder()
            .putString("log_level",
                () -> String.valueOf(preferences.getLogLevel()),
                value -> preferences.setLogLevel(context, Integer.parseInt(value)))
            .putBoolean("terminal_view_key_logging_enabled",
                preferences::isTerminalViewKeyLoggingEnabled,
                preferences::setTerminalViewKeyLoggingEnabled)
            .putBoolean("plugin_error_notifications_enabled",
                () -> preferences.arePluginErrorNotificationsEnabled(false),
                preferences::setPluginErrorNotificationsEnabled)
            .putBoolean("crash_report_notifications_enabled",
                () -> preferences.areCrashReportNotificationsEnabled(false),
                preferences::setCrashReportNotificationsEnabled)
            .build();
    }

    @Override
    protected int getLogLevel(@NonNull Context context) {
        TermuxAppSharedPreferences preferences = TermuxAppSharedPreferences.build(context, true);
        return preferences == null ? 1 : preferences.getLogLevel();
    }
}

