 21	    public static final class Builder {
 22	
 23	        private final Map<String, PreferenceBinding> mBindings = new HashMap<>();
 24	
 25	        public Builder putString(@NonNull String key, @Nullable Supplier<String> getter, @Nullable Consumer<String> setter) {
 26	            mBindings.put(key, PreferenceBinding.forString(getter, setter));
 27	            return this;
 28	        }
 29	
 30	        public Builder putBoolean(@NonNull String key, @Nullable Supplier<Boolean> getter, @Nullable Consumer<Boolean> setter) {
 31	            mBindings.put(key, PreferenceBinding.forBoolean(getter, setter));
 32	            return this;
 33	        }
