 40	    private static final class PreferenceBinding {
 41	
 42	        @Nullable
 43	        private final Supplier<String> mStringGetter;
 44	        @Nullable
 45	        private final Consumer<String> mStringSetter;
 46	        @Nullable
 47	        private final Supplier<Boolean> mBooleanGetter;
 48	        @Nullable
 49	        private final Consumer<Boolean> mBooleanSetter;
 50	
 51	        private PreferenceBinding(@Nullable Supplier<String> stringGetter, @Nullable Consumer<String> stringSetter,
 52	                                  @Nullable Supplier<Boolean> booleanGetter, @Nullable Consumer<Boolean> booleanSetter) {
 53	            mStringGetter = stringGetter;
 54	            mStringSetter = stringSetter;
 55	            mBooleanGetter = booleanGetter;
 56	            mBooleanSetter = booleanSetter;
 57	        }
 58	
 59	        private static PreferenceBinding forString(@Nullable Supplier<String> getter, @Nullable Consumer<String> setter) {
 60	            return new PreferenceBinding(getter, setter, null, null);
 61	        }
 62	
 63	        private static PreferenceBinding forBoolean(@Nullable Supplier<Boolean> getter, @Nullable Consumer<Boolean> setter) {
 64	            return new PreferenceBinding(null, null, getter, setter);
 65	        }
 66	    }
 67	
 68	    @Override
 69	    @Nullable
 70	    public String getString(String key, @Nullable String defValue) {
 71	        PreferenceBinding binding = mBindings.get(key);
 72	        if (binding == null || binding.mStringGetter == null) return defValue;
 73	
 74	        String value = binding.mStringGetter.get();
 75	        return value == null ? defValue : value;
 76	    }
 77	
 78	    @Override
 79	    public void putString(String key, @Nullable String value) {
 80	        PreferenceBinding binding = mBindings.get(key);
 81	        if (binding == null || binding.mStringSetter == null || value == null) return;
 82	
 83	        binding.mStringSetter.accept(value);
 84	    }
 85	
 86	    @Override
 87	    public boolean getBoolean(String key, boolean defValue) {
 88	        PreferenceBinding binding = mBindings.get(key);
 89	        if (binding == null || binding.mBooleanGetter == null) return defValue;
 90	
 91	        Boolean value = binding.mBooleanGetter.get();
 92	        return value == null ? defValue : value;
 93	    }
 94	
