 96	    public void putBoolean(String key, boolean value) {
 97	        PreferenceBinding binding = mBindings.get(key);
 98	        if (binding == null || binding.mBooleanSetter == null) return;
 99	
100	        binding.mBooleanSetter.accept(value);
